function bestHopScore(nums: number[], k: number): number {
  const n = nums.length;
  const best = new Array(n).fill(-Infinity);
  best[0] = nums[0];
  for (let i = 1; i < n; i++) {
    for (let j = Math.max(0, i - k); j < i; j++) best[i] = Math.max(best[i], best[j]);
    best[i] += nums[i];
  }
  return best[n - 1];
}

