class Solution:
    def bestHopScore(self, nums: List[int], k: int) -> int:
        best = [nums[0]] + [0] * (len(nums) - 1)
        for i in range(1, len(nums)):
            best[i] = nums[i] + max(best[max(0, i - k):i])
        return best[-1]

