function bestHopScore(nums: number[], k: number): number {
  // binary max-heap of [score, index]
  const h: [number, number][] = [];
  const push = (x: [number, number]) => {
    h.push(x);
    let i = h.length - 1;
    while (i > 0) {
      const p = (i - 1) >> 1;
      if (h[p][0] >= h[i][0]) break;
      [h[p], h[i]] = [h[i], h[p]];
      i = p;
    }
  };
  const pop = () => {
    const last = h.pop()!;
    if (!h.length) return;
    h[0] = last;
    let i = 0;
    for (;;) {
      const l = 2 * i + 1, r = l + 1;
      let m = i;
      if (l < h.length && h[l][0] > h[m][0]) m = l;
      if (r < h.length && h[r][0] > h[m][0]) m = r;
      if (m === i) break;
      [h[m], h[i]] = [h[i], h[m]];
      i = m;
    }
  };
  let cur = nums[0];
  push([cur, 0]);
  for (let i = 1; i < nums.length; i++) {
    while (h[0][1] < i - k) pop();
    cur = nums[i] + h[0][0];
    push([cur, i]);
  }
  return cur;
}

