function bestHopScore(nums: number[], k: number): number {
  const n = nums.length;
  const best = new Array<number>(n);
  const dq = new Array<number>(n);
  let head = 0, tail = 0;
  best[0] = nums[0];
  dq[tail++] = 0;
  for (let i = 1; i < n; i++) {
    if (dq[head] < i - k) head++;
    best[i] = nums[i] + best[dq[head]];
    while (tail > head && best[dq[tail - 1]] <= best[i]) tail--;
    dq[tail++] = i;
  }
  return best[n - 1];
}

