    def bestHopScore(self, nums: List[int], k: int) -> int:
        best = [0] * len(nums)
        best[0] = nums[0]
        dq = deque([0])
        for i in range(1, len(nums)):
            if dq[0] < i - k:
                dq.popleft()
            best[i] = nums[i] + best[dq[0]]
            while dq and best[dq[-1]] <= best[i]:
                dq.pop()
            dq.append(i)
        return best[-1]

